mapper.select:
select L1.user_id as resource_id, count(L1.lesson_id) as lesson_record_count, count(L2.id) as finish_report_count, sum(L3.score) / if(count(L2.id)=0, 1, count(L2.id)) as report_average, count(L4.id) as finish_practice_count from oj_lesson_record L1 left join (select * from oj_note where create_time >= #{start_time} and create_time <= #{end_time}) L2 on L2.note_type = #{report_code} and L1.user_id = L2.user_id and L1.lesson_id = L2.business_id left join oj_note_evaluate L3 on L2.resource_id = L3.note_id left join (select * from oj_lesson_paper_evaluate where create_time >= #{start_time} and create_time <= #{end_time} and (level = 1 or level = 2)) L4 on L1.lesson_id = L4.lesson_id and L1.user_id = L4.submit_user_id
L1.lesson_id in (select resource_id from oj_course_lesson) and L1.user_id in #{user_id} and L1.create_time >= #{start_time} and L1.create_time <= #{end_time}
group by L1.user_id;

select user_id, count(*) as `count` from oj_lesson_record
where user_id in #{user_id}
and lesson_id in 
group by user_id
;

select T1.user_id, count(T1.resource_id) as `count`
from oj_note T1
where T1.note_type = #{report_code} and T1.user_id in #{user_id}
group by T1.user_id
;

select submit_user_id as user_id, sum(case when level = 1 then  1 when level = 2 then 1  else 0 ENd) as integral
from oj_lesson_paper_evaluate where create_time >= #{start_time} and create_time <= #{end_time}
and  submit_user_id in #{user_id}
and lesson_id in 
GROUP BY submit_user_id
